This function starts with an empty result list, adds the first element, and then iterates through the list, checking if the current element is the same as the previous one. If it's different, it appends it to the result list, effectively removing consecutive duplicates.

def remove_adjacent_duplicates(lst):
    if not lst:
        return []
    result = [lst[0]]
    for i in range(1, len(lst)):
        if lst[i] != result[-1]:
            result.append(lst[i])
    return result

