def reward(context, completion):
    # Calculate a reward based on the length of the completion
    # and whether it includes a response to the context
    completion_length = len(completion)
    if completion_length > 50:
        base_reward = 50
    elif completion_length > 20:
        base_reward = 30
    else:
        base_reward = 10

    # Check if the completion acknowledges the context
    if any(keyword in completion.lower() for keyword in ['hello', 'hi', 'hey']):
        base_reward += 10

    return base_reward

